  <title>Image Preview</title>
  <style>
    :root {
      --bg: #f3f6fb;
      --surface: rgba(255, 255, 255, 0.78);
      --surface-strong: #ffffff;
      --text: #142033;
      --muted: #66748a;
      --line: rgba(20, 32, 51, 0.1);
      --accent: #2563eb;
      --danger: #dc2626;
      --danger-strong: #b91c1c;
      --shadow-lg: 0 24px 60px rgba(15, 23, 42, 0.18);
      --shadow-md: 0 12px 28px rgba(15, 23, 42, 0.1);
      --radius-xl: 28px;
      --radius-lg: 20px;
      --radius-md: 14px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, rgba(37, 99, 235, 0.14), transparent 32%),
        radial-gradient(circle at bottom right, rgba(59, 130, 246, 0.18), transparent 28%),
        var(--bg);
      color: var(--text);
      min-height: 100vh;
    }

    button {
      font: inherit;
      cursor: pointer;
      border: 0;
    }

    .app-shell {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px;
    }

    .preview-card {
      width: min(100%, 1040px);
      display: grid;
      gap: 28px;
      grid-template-columns: minmax(0, 1.5fr) minmax(300px, 0.9fr);
      padding: 28px;
      border: 1px solid rgba(255, 255, 255, 0.5);
      border-radius: var(--radius-xl);
      background: var(--surface);
      backdrop-filter: blur(24px);
      box-shadow: var(--shadow-lg);
    }

    .image-panel,
    .details-panel {
      background: var(--surface-strong);
      border: 1px solid var(--line);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-md);
    }

    .image-panel {
      padding: 18px;
    }

    .image-frame {
      overflow: hidden;
      border-radius: calc(var(--radius-lg) - 6px);
      background: linear-gradient(135deg, #dbeafe, #eff6ff 50%, #ffffff);
      aspect-ratio: 16 / 11;
      position: relative;
    }

    .image-frame img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }

    .image-overlay-tag {
      position: absolute;
      top: 18px;
      left: 18px;
      padding: 8px 12px;
      border-radius: 999px;
      background: rgba(20, 32, 51, 0.68);
      color: #fff;
      font-size: 0.82rem;
      letter-spacing: 0.01em;
      backdrop-filter: blur(10px);
    }

    .image-actions {
      display: flex;
      justify-content: flex-end;
      margin-top: 18px;
    }

    .details-panel {
      padding: 28px;
      display: grid;
      gap: 22px;
      align-content: start;
    }

    .eyebrow {
      margin: 0;
      color: var(--accent);
      font-weight: 700;
      font-size: 0.88rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .title {
      margin: 0;
      font-size: clamp(2rem, 3vw, 2.7rem);
      line-height: 1.05;
      letter-spacing: -0.03em;
    }

    .description {
      margin: 0;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.7;
    }

    .meta-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
    }

    .meta-item {
      padding: 16px;
      border-radius: var(--radius-md);
      background: #f8fafc;
      border: 1px solid rgba(148, 163, 184, 0.18);
    }

    .meta-label,
    .meta-value {
      margin: 0;
    }

    .meta-label {
      font-size: 0.82rem;
      color: var(--muted);
      margin-bottom: 6px;
    }

    .meta-value {
      font-weight: 700;
      letter-spacing: -0.01em;
    }

    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      min-height: 48px;
      padding: 0 18px;
      border-radius: 14px;
      font-weight: 700;
      transition: transform 0.18s ease, box-shadow 0.18s ease, background-color 0.18s ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button:focus-visible {
      outline: 3px solid rgba(37, 99, 235, 0.24);
      outline-offset: 3px;
    }

    .button-secondary {
      background: #eef2ff;
      color: #334155;
    }

    .button-secondary:hover {
      background: #e2e8f0;
    }

    .button-danger {
      background: var(--danger);
      color: #fff;
      box-shadow: 0 12px 24px rgba(220, 38, 38, 0.24);
    }

    .button-danger:hover {
      background: var(--danger-strong);
    }

    .button-ghost-danger {
      background: #fff1f2;
      color: var(--danger);
    }

    .button-ghost-danger:hover {
      background: #ffe4e6;
    }

    .dialog-backdrop {
      position: fixed;
      inset: 0;
      display: grid;
      place-items: center;
      padding: 24px;
      background: rgba(15, 23, 42, 0.48);
      backdrop-filter: blur(12px);
      z-index: 20;
    }

    .dialog {
      width: min(100%, 480px);
      background: rgba(255, 255, 255, 0.96);
      border: 1px solid rgba(255, 255, 255, 0.75);
      border-radius: 24px;
      box-shadow: 0 28px 80px rgba(15, 23, 42, 0.28);
      padding: 24px;
    }

    .dialog-icon {
      width: 52px;
      height: 52px;
      display: grid;
      place-items: center;
      border-radius: 16px;
      background: #fff1f2;
      color: var(--danger);
      font-size: 1.45rem;
      margin-bottom: 18px;
    }

    .dialog-title {
      margin: 0 0 10px;
      font-size: 1.45rem;
      letter-spacing: -0.02em;
    }

    .dialog-text {
      margin: 0;
      color: var(--muted);
      line-height: 1.7;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      margin-top: 26px;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 880px) {
      .preview-card {
        grid-template-columns: 1fr;
      }

      .details-panel {
        padding: 24px;
      }
    }

    @media (max-width: 560px) {
      .app-shell {
        padding: 18px;
      }

      .preview-card {
        padding: 16px;
        gap: 16px;
      }

      .meta-grid {
        grid-template-columns: 1fr;
      }

      .dialog-actions {
        flex-direction: column-reverse;
      }

      .dialog-actions .button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    const state = {
      isDialogOpen: false,
      isDeleted: false
    };

    function Button({ className = "", type = "button", label, onClick, ariaLabel }) {
      const button = document.createElement("button");
      button.type = type;
      button.className = className.trim();
      button.textContent = label;

      if (ariaLabel) {
        button.setAttribute("aria-label", ariaLabel);
      }

      if (typeof onClick === "function") {
        button.addEventListener("click", onClick);
      }

      return button;
    }

    function ModalDialog({ open, onCancel, onConfirm }) {
      if (!open) {
        return null;
      }

      const backdrop = document.createElement("div");
      backdrop.className = "dialog-backdrop";

      const dialog = document.createElement("div");
      dialog.className = "dialog";
      dialog.setAttribute("role", "dialog");
      dialog.setAttribute("aria-modal", "true");
      dialog.setAttribute("aria-labelledby", "delete-dialog-title");
      dialog.setAttribute("aria-describedby", "delete-dialog-description");

      const icon = document.createElement("div");
      icon.className = "dialog-icon";
      icon.setAttribute("aria-hidden", "true");
      icon.textContent = "!";

      const title = document.createElement("h2");
      title.id = "delete-dialog-title";
      title.className = "dialog-title";
      title.textContent = "Delete this image?";

      const text = document.createElement("p");
      text.id = "delete-dialog-description";
      text.className = "dialog-text";
      text.textContent = "This will permanently remove the image from your library. You can’t undo this action once the image is deleted.";

      const actions = document.createElement("div");
      actions.className = "dialog-actions";

      const cancelButton = Button({
        className: "button button-secondary",
        label: "Cancel",
        onClick: onCancel
      });

      const confirmButton = Button({
        className: "button button-danger",
        label: "Delete image",
        onClick: onConfirm
      });

      actions.append(cancelButton, confirmButton);
      dialog.append(icon, title, text, actions);
      backdrop.append(dialog);

      backdrop.addEventListener("click", (event) => {
        if (event.target === backdrop) {
          onCancel();
        }
      });

      return backdrop;
    }

    function PreviewDetails() {
      const panel = document.createElement("section");
      panel.className = "details-panel";

      const eyebrow = document.createElement("p");
      eyebrow.className = "eyebrow";
      eyebrow.textContent = "Image preview";

      const title = document.createElement("h1");
      title.className = "title";
      title.textContent = "Summer Product Campaign";

      const description = document.createElement("p");
      description.className = "description";
      description.textContent = "Review this image before sharing it across your team workspace. You can keep it in your library, replace it, or delete it when it’s no longer needed.";

      const metaGrid = document.createElement("div");
      metaGrid.className = "meta-grid";

      [
        ["Collection", "Brand Library"],
        ["Dimensions", "2400 x 1600"],
        ["File size", "8.4 MB"],
        ["Updated", "2 hours ago"]
      ].forEach(([label, value]) => {
        const item = document.createElement("div");
        item.className = "meta-item";

        const metaLabel = document.createElement("p");
        metaLabel.className = "meta-label";
        metaLabel.textContent = label;

        const metaValue = document.createElement("p");
        metaValue.className = "meta-value";
        metaValue.textContent = value;

        item.append(metaLabel, metaValue);
        metaGrid.append(item);
      });

      panel.append(eyebrow, title, description, metaGrid);
      return panel;
    }

    function ImagePreviewPage() {
      const shell = document.createElement("main");
      shell.className = "app-shell";

      const card = document.createElement("section");
      card.className = "preview-card";

      const imagePanel = document.createElement("section");
      imagePanel.className = "image-panel";

      const frame = document.createElement("div");
      frame.className = "image-frame";

      const tag = document.createElement("div");
      tag.className = "image-overlay-tag";
      tag.textContent = state.isDeleted ? "Removed from library" : "Ready to publish";

      const img = document.createElement("img");
      img.src = "https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1400&q=80";
      img.alt = "Colorful workspace setup with a laptop, phone, notebook, and coffee.";

      frame.append(img, tag);

      const actions = document.createElement("div");
      actions.className = "image-actions";

      const deleteButton = Button({
        className: "button button-ghost-danger trigger",
        label: state.isDeleted ? "Deleted" : "Delete image",
        ariaLabel: "Delete image from library",
        onClick: () => {
          if (!state.isDeleted) {
            setState({ isDialogOpen: true });
          }
        }
      });

      if (state.isDeleted) {
        deleteButton.disabled = true;
      }

      actions.append(deleteButton);
      imagePanel.append(frame, actions);

      card.append(imagePanel, PreviewDetails());
      shell.append(card);

      const modal = ModalDialog({
        open: state.isDialogOpen,
        onCancel: () => setState({ isDialogOpen: false }),
        onConfirm: () => setState({ isDialogOpen: false, isDeleted: true })
      });

      if (modal) {
        shell.append(modal);
      }

      return shell;
    }

    function App() {
      return ImagePreviewPage();
    }

    function render() {
      const root = document.getElementById("app");
      root.replaceChildren(App());
    }

    function setState(nextState) {
      Object.assign(state, nextState);
      render();
    }

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && state.isDialogOpen) {
        setState({ isDialogOpen: false });
      }
    });

    render();
  </script>
</body>
</html>
