      color: #fff;
      box-shadow: 0 12px 24px rgba(220, 38, 38, 0.24);
    }

    .button-danger:hover {
      background: var(--danger-strong);
    }

    .button-ghost-danger {
      background: #fff1f2;
      color: var(--danger);
    }

    .button-ghost-danger:hover {
      background: #ffe4e6;
