<body>
  <div id="app"></div>

  <script>
    const state = {
      isDialogOpen: false,
      isDeleted: false
    };

    function Button({ className = "", type = "button", label, onClick, ariaLabel }) {
      const button = document.createElement("button");
      button.type = type;
      button.className = className.trim();
      button.textContent = label;

      if (ariaLabel) {
        button.setAttribute("aria-label", ariaLabel);
      }

      if (typeof onClick === "function") {
        button.addEventListener("click", onClick);
      }

      return button;
    }

    function ModalDialog({ open, onCancel, onConfirm }) {
      if (!open) {
        return null;
      }

      const backdrop = document.createElement("div");
      backdrop.className = "dialog-backdrop";

      const dialog = document.createElement("div");
      dialog.className = "dialog";
      dialog.setAttribute("role", "dialog");
      dialog.setAttribute("aria-modal", "true");
      dialog.setAttribute("aria-labelledby", "delete-dialog-title");
      dialog.setAttribute("aria-describedby", "delete-dialog-description");

      const icon = document.createElement("div");
      icon.className = "dialog-icon";
      icon.setAttribute("aria-hidden", "true");
      icon.textContent = "!";

      const title = document.createElement("h2");
      title.id = "delete-dialog-title";
      title.className = "dialog-title";
      title.textContent = "Delete this image?";

      const text = document.createElement("p");
      text.id = "delete-dialog-description";
      text.className = "dialog-text";
      text.textContent = "This will permanently remove the image from your library. You can't undo this action once the image is deleted.";

      const actions = document.createElement("div");
      actions.className = "dialog-actions";

      const cancelButton = Button({
        className: "button button-secondary",
        label: "Cancel",
        onClick: onCancel
      });

      const confirmButton = Button({
        className: "button button-danger",
        label: "Delete image",
        onClick: onConfirm
      });

      actions.append(cancelButton, confirmButton);
      dialog.append(icon, title, text, actions);
      backdrop.append(dialog);

      backdrop.addEventListener("click", (event) => {
        if (event.target === backdrop) {
          onCancel();
        }
      });

      return backdrop;
    }

    function PreviewDetails() {
      const panel = document.createElement("section");
      panel.className = "details-panel";

      const eyebrow = document.createElement("p");
      eyebrow.className = "eyebrow";
      eyebrow.textContent = "Image preview";

      const title = document.createElement("h1");
      title.className = "title";
      title.textContent = "Summer Product Campaign";

      const description = document.createElement("p");
      description.className = "description";
      description.textContent = "Review this image before sharing it across your team workspace. You can keep it in your library, replace it, or delete it when it’s no longer needed.";

      const metaGrid = document.createElement("div");
      metaGrid.className = "meta-grid";

      [
        ["Collection", "Brand Library"],
        ["Dimensions", "2400 x 1600"],
        ["File size", "8.4 MB"],
        ["Updated", "2 hours ago"]
      ].forEach(([label, value]) => {
        const item = document.createElement("div");
        item.className = "meta-item";

        const metaLabel = document.createElement("p");
        metaLabel.className = "meta-label";
        metaLabel.textContent = label;

        const metaValue = document.createElement("p");
        metaValue.className = "meta-value";
        metaValue.textContent = value;

        item.append(metaLabel, metaValue);
        metaGrid.append(item);
      });

      panel.append(eyebrow, title, description, metaGrid);
      return panel;
    }

    function ImagePreviewPage() {
      const shell = document.createElement("main");
      shell.className = "app-shell";

      const card = document.createElement("section");
      card.className = "preview-card";

      const imagePanel = document.createElement("section");
      imagePanel.className = "image-panel";

      const frame = document.createElement("div");
      frame.className = "image-frame";

      const tag = document.createElement("div");
      tag.className = "image-overlay-tag";
      tag.textContent = state.isDeleted ? "Removed from library" : "Ready to publish";

      const img = document.createElement("img");
      img.src = "https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1400&q=80";
      img.alt = "Colorful workspace setup with a laptop, phone, notebook, and coffee.";

      frame.append(img, tag);

      const actions = document.createElement("div");
      actions.className = "image-actions";

      const deleteButton = Button({
        className: "button button-ghost-danger trigger",
        label: state.isDeleted ? "Deleted" : "Delete image",
        ariaLabel: "Delete image from library",
        onClick: () => {
          if (!state.isDeleted) {
            setState({ isDialogOpen: true });
          }
        }
      });

      if (state.isDeleted) {
        deleteButton.disabled = true;
      }

      actions.append(deleteButton);
      imagePanel.append(frame, actions);

      card.append(imagePanel, PreviewDetails());
      shell.append(card);

      const modal = ModalDialog({
        open: state.isDialogOpen,
        onCancel: () => setState({ isDialogOpen: false }),
        onConfirm: () => setState({ isDialogOpen: false, isDeleted: true })
      });

      if (modal) {
        shell.append(modal);
      }

      return shell;
    }

    function App() {
      return ImagePreviewPage();
    }

    function render() {
      const root = document.getElementById("app");
      root.replaceChildren(App());
    }

    function setState(nextState) {
      Object.assign(state, nextState);
      render();
    }

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && state.isDialogOpen) {
        setState({ isDialogOpen: false });
      }
    });

    render();
  </script>
